		{
			if(m_isForward || !m_win)
				break;
			m_win->winHide(TRUE);
			m_isFinished = TRUE;
		}
		break;
	// BFME: no GUILogoMouseOver string/audio in retail; cases 1-5 share hide+drawState.
	case SCALEUPTRANSITION_1:
	case SCALEUPTRANSITION_2:
	case SCALEUPTRANSITION_3:
